@dataclass(frozen=True, slots=True)
class CommitRevealSnapshot:
    """Canonical immutable Commit and Reveal Record sets for one Lane Round."""

    commits: tuple[CommitRecord, ...] = ()
    reveals: tuple[RevealRecord, ...] = ()

    def __post_init__(self) -> None:
        commits = _ordered_unique(self.commits, "Commit")
        reveals = _ordered_unique(self.reveals, "Reveal")
        commit_ids = {record.ticket_id for record in commits}
        if any(record.ticket_id not in commit_ids for record in reveals):
            raise StateInvariantError("Reveal Record has no Commit Record")
        object.__setattr__(self, "commits", commits)
        object.__setattr__(self, "reveals", reveals)

    def commit(self, ticket_id: bytes) -> CommitRecord | None:
        return _find_record(self.commits, ticket_id)

    def reveal(self, ticket_id: bytes) -> RevealRecord | None:
        return _find_record(self.reveals, ticket_id)

    def with_commit(self, record: CommitRecord) -> CommitRevealSnapshot:
        if self.commit(record.ticket_id) is not None:
            raise StateInvariantError("Commit Record key already exists")
        return CommitRevealSnapshot(self.commits + (record,), self.reveals)

    def with_reveal(self, record: RevealRecord) -> CommitRevealSnapshot:
        if self.commit(record.ticket_id) is None:
            raise StateInvariantError("Reveal Record has no Commit Record")
        if self.reveal(record.ticket_id) is not None:
            raise StateInvariantError("Reveal Record key already exists")
        return CommitRevealSnapshot(self.commits, self.reveals + (record,))


