def _ordered_unique(
    records: tuple[CommitRecord, ...] | tuple[RevealRecord, ...],
    kind: str,
) -> tuple:
    if not isinstance(records, tuple):
        raise StateInvariantError(f"{kind} Records must be an immutable tuple")
    ordered = tuple(sorted(records, key=lambda record: record.ticket_id))
    if any(
        left.ticket_id == right.ticket_id
        for left, right in zip(ordered, ordered[1:])
    ):
        raise StateInvariantError(f"{kind} Record set contains a duplicate Ticket ID")
    return ordered


def _find_record(records: tuple, ticket_id: bytes):
    for record in records:
        if record.ticket_id == ticket_id:
            return record
    return None


def _require_bytes(
    value: bytes, minimum: int, maximum: int, name: str
) -> None:
    if not isinstance(value, bytes) or not minimum <= len(value) <= maximum:
        if minimum == maximum:
            raise ValueError(f"{name} must contain exactly {minimum} bytes")
        raise ValueError(f"{name} must contain {minimum} through {maximum} bytes")


def _require_uint(value: int, bits: int, name: str) -> None:
    if type(value) is not int or not 0 <= value < 1 << bits:
        raise ValueError(f"{name} must be an unsigned {bits}-bit integer")


def _require_lane_round_key(value: tuple[object, ...]) -> None:
    if not isinstance(value, tuple) or len(value) != 6:
        raise ValueError("lane_round_key must be an immutable six-field tuple")
    try:
        canonical = tuple(
            lane_round_key(value[1], value[2], value[3], value[4], value[5])
        )
    except (CanonicalTranscriptError, IndexError) as exc:
        raise ValueError("lane_round_key is malformed") from exc
    if value != canonical:
        raise ValueError("lane_round_key is not the frozen v0 canonical key")
